import{_ as o,a0 as p,w as s,s as i,I as n,x as e,a1 as l,A as r,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"英特爾 Optane：用於數據中心內存緩存 | LCTT x X-CMD","titleTemplate":false,"description":"英特爾 Optane：用於數據中心內存緩存 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"英特爾 Optane：用於數據中心內存緩存 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"英特爾 Optane：用於數據中心內存緩存 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20190404 Intel formally launches Optane for data center memory caching","title":"英特爾 Optane：用於數據中心內存緩存","tag":"202102","desc":""},"relativePath":"202102/20190404 Intel formally launches Optane for data center memory caching.md","filePath":"[post].md"}'),d={name:"202102/20190404 Intel formally launches Optane for data center memory caching.md"};function u(f,t,D,O,w,g){const a=p("Link");return s(),i("div",null,[t[24]||(t[24]=n("h1",{id:"英特爾-optane-用於數據中心內存緩存",tabindex:"-1"},[e("英特爾 Optane：用於數據中心內存緩存 "),n("a",{class:"header-anchor",href:"#英特爾-optane-用於數據中心內存緩存","aria-label":"Permalink to “英特爾 Optane：用於數據中心內存緩存”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202102/12/111720yq1rvxcncjdsjb0g.jpg",alt:""})],-1)),t[26]||(t[26]=n("blockquote",null,[n("p",null,"英特爾推出了包含 3D Xpoint 內存技術的 Optane 持久內存產品線。英特爾的這個解決方案介乎於 DRAM 和 NAND 中間，以此來提升性能。")],-1)),t[27]||(t[27]=n("p",null,[n("img",{src:"https://images.idgesg.net/images/article/2018/06/intel-optane-persistent-memory-100760427-large.jpg",alt:"Intel"})],-1)),n("p",null,[t[1]||(t[1]=e("英特爾在 2019 年 4 月的",-1)),l(a,{href:"https://www.networkworld.com/article/3386142/intel-unveils-an-epic-response-to-amds-server-push.html"},{default:r(()=>[...t[0]||(t[0]=[e("大規模數據中心活動",-1)])]),_:1}),t[2]||(t[2]=e("中正式推出 Optane 持久內存產品線。它已經問世了一段時間，但是目前的 Xeon 服務器處理器還不能充分利用它。而新的 Xeon8200 和 9200 系列可以充分利用 Optane 持久內存的優勢。",-1))]),t[28]||(t[28]=n("p",null,"由於 Optane 是英特爾的產品（與美光合作開發），所以意味着 AMD 和 ARM 的服務器處理器不能夠支持它。",-1)),n("p",null,[t[4]||(t[4]=e("正如",-1)),l(a,{href:"https://www.networkworld.com/article/3279271/intel-launches-optane-the-go-between-for-memory-and-storage.html"},{default:r(()=>[...t[3]||(t[3]=[e("我之前所説的",-1)])]),_:1}),t[5]||(t[5]=e("，OptaneDC 持久內存採用與美光合作研發的 3D Xpoint 內存技術。3D Xpoint 是一種比 SSD 更快的非易失性內存，速度幾乎與 DRAM 相近，而且它具有 NAND 閃存的持久性。",-1))]),n("p",null,[t[7]||(t[7]=e("第一個 3D Xpoint 產品是被稱為英特爾“尺子”的 SSD，因為它們被設計成細長的樣子，很像尺子的形狀。它們被設計這樣是為了適合 1u 的服務器機架。在發佈的公告中，英特爾推出了新的利用四芯或者 QLC 3D NAND 內存的英特爾 SSD D5-P4325 ",-1)),l(a,{href:"https://www.theregister.co.uk/2018/02/02/ruler_and_miniruler_ssd_formats_look_to_banish_diskstyle_drives/"},{default:r(()=>[...t[6]||(t[6]=[e("尺子",-1)])]),_:1}),t[8]||(t[8]=e(" SSD，可以在 1U 的服務器機架上放 1PB 的存儲。",-1))]),t[29]||(t[29]=m('<p>OptaneDC 持久內存的可用容量最初可以通過使用 128GB 的 DIMM 達到 512GB。英特爾數據中心集團執行副總裁及總經理 Navin Shenoy 説：“OptaneDC 持久內存可達到的容量是 DRAM 的 2 到 4 倍。”</p><p>他説：“我們希望服務器系統的容量可以擴展到每個插槽 4.5TB 或者 8 個插槽 36TB，這是我們第一代 Xeon 可擴展芯片的 3 倍。”</p><h3 id="英特爾optane內存的使用和速度" tabindex="-1">英特爾Optane內存的使用和速度 <a class="header-anchor" href="#英特爾optane內存的使用和速度" aria-label="Permalink to “英特爾Optane內存的使用和速度”">​</a></h3><p>Optane 有兩種不同的運行模式：內存模式和應用直連模式。內存模式是將 DRAM 放在 Optane 內存之上，將 DRAM 作為 Optane 內存的緩存。應用直連模式是將 DRAM 和 OptaneDC 持久內存一起作為內存來最大化總容量。並不是每個工作負載都適合這種配置，所以應該在對延遲不敏感的應用程序中使用。正如英特爾推廣的那樣，Optane 的主要使用情景是內存模式。</p><p>幾年前，當 3D Xpoint 最初發布時，英特爾宣稱 Optane 的速度是 NAND 的 1000 倍，耐用是 NAND 的 1000 倍，密度潛力是 DRAM 的 10 倍。這雖然有點誇張，但這些因素確實很令人着迷。</p><p>在 256B 的連續 4 個緩存行中使用 Optane 內存可以達到 8.3GB/秒的讀速度和 3.0GB/秒的寫速度。與 SATA SSD 的 500MB/秒左右的讀/寫速度相比，可以看到性能有很大提升。請記住，Optane 充當內存，所以它會緩存被頻繁訪問的 SSD 中的內容。</p><p>這是瞭解 OptaneDC 的關鍵。它能將非常大的數據集存儲在離內存非常近的位置，因此具有很低延遲的 CPU 可以最小化訪問較慢的存儲子系統的訪問延遲，無論存儲是 SSD 還是 HDD。現在，它提供了一種可能性，即把多個 TB 的數據放在非常接近 CPU 的地方，以實現更快的訪問。</p><h3 id="optane-內存的一個挑戰" tabindex="-1">Optane 內存的一個挑戰 <a class="header-anchor" href="#optane-內存的一個挑戰" aria-label="Permalink to “Optane 內存的一個挑戰”">​</a></h3><p>唯一真正的挑戰是 Optane 插進內存所在的 DIMM 插槽。現在有些主板的每個 CPU 有多達 16 個 DIMM 插槽，但是這仍然是客户和設備製造商之間需要平衡的電路板空間：Optane 還是內存。有一些 Optane 驅動採用了 PCIe 接口進行連接，可以減輕主板上內存的擁擠。</p><p>3D Xpoint 由於它寫數據的方式，提供了比傳統的 NAND 閃存更高的耐用性。英特爾承諾 Optane 提供 5 年保修期，而很多 SSD 只提供 3 年保修期。</p><hr>',11)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),l(a,{href:"https://www.networkworld.com/article/3387117/intel-formally-launches-optane-for-data-center-memory-caching.html#tk.rss_all"},{default:r(()=>[...t[9]||(t[9]=[e("https://www.networkworld.com/article/3387117/intel-formally-launches-optane-for-data-center-memory-caching.html#tk.rss_all",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("作者：",-1)),l(a,{href:"https://www.networkworld.com/author/Andy-Patrizio/"},{default:r(()=>[...t[11]||(t[11]=[e("Andy Patrizio",-1)])]),_:1}),t[16]||(t[16]=e(" 選題：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[12]||(t[12]=[e("lujun9972",-1)])]),_:1}),t[17]||(t[17]=e(" 譯者：",-1)),l(a,{href:"https://github.com/ShuyRoy"},{default:r(()=>[...t[13]||(t[13]=[e("RiaXu",-1)])]),_:1}),t[18]||(t[18]=e(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:r(()=>[...t[20]||(t[20]=[e("Linux中國",-1)])]),_:1}),t[23]||(t[23]=e(" 榮譽推出",-1))])])}const y=o(d,[["render",u]]);export{S as __pageData,y as default};
